if (isNewsletter) {
    logger?.info({ key: cacheableKey }, 'Preparing raw media for newsletter');
    const { filePath, fileSha256, fileLength } = await getRawMediaUploadData(uploadData.media, options.mediaTypeOverride || mediaType, logger);
    try {
        const { directPath, thumbnailDirectPath, thumbnailSha256 } = await options.upload(filePath, {
            fileEncSha256B64: fileSha256.toString('base64'),
            mediaType,
            timeoutMs: options.mediaUploadTimeoutMs,
            newsletter: true
        });
        if (!directPath) {
            throw new Boom('Newsletter upload returned no directPath', { statusCode: 502 });
        }
        const obj = WAProto.Message.fromObject({
            [`${mediaType}Message`]: MessageTypeProto[mediaType].fromObject({
                ...uploadData,
                directPath,
                fileSha256,
                fileLength,
                thumbnailDirectPath,
                thumbnailSha256: thumbnailSha256 ? Buffer.from(thumbnailSha256, 'base64') : undefined,
                // Raw newsletter media is referenced by the server's signed directPath.
                url: undefined,
                mediaKey: undefined,
                fileEncSha256: undefined,
                media: undefined
            })
        });
        if (uploadData.ptv) {
            obj.ptvMessage = obj.videoMessage;
            delete obj.videoMessage;
        }
        if (obj.stickerMessage) {
            obj.stickerMessage.stickerSentTs = Date.now();
        }
        if (cacheableKey) {
            await options.mediaCache.set(cacheableKey, WAProto.Message.encode(obj).finish());
        }
        return obj;
    }
    finally {
        await fs.unlink(filePath).catch(() => {});
    }
}

